--
-- Table structure for table `data_source_entry`
--

DROP TABLE IF EXISTS `data_source_entry`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `data_source_entry` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `data_source_id` bigint unsigned NOT NULL,
  `year` smallint NOT NULL,
  `quarter` tinyint unsigned DEFAULT NULL,
  `values_json` json NOT NULL,
  `note` text,
  `recorded_by` varchar(20) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_dse_recorder` (`recorded_by`),
  KEY `idx_dse_period` (`data_source_id`,`year`,`quarter`),
  CONSTRAINT `fk_dse_recorder` FOREIGN KEY (`recorded_by`) REFERENCES `faculty` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_dse_source` FOREIGN KEY (`data_source_id`) REFERENCES `data_source` (`id`) ON DELETE CASCADE,
  CONSTRAINT `data_source_entry_chk_1` CHECK (((`quarter` is null) or (`quarter` between 1 and 4)))
) ENGINE=InnoDB AUTO_INCREMENT=653 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

