CREATE TABLE `data_source_link` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `data_source_id` bigint unsigned NOT NULL,
  `library_kpi_id` bigint unsigned DEFAULT NULL,
  `library_metric_id` bigint unsigned DEFAULT NULL,
  `mappings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `note` varchar(1000) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `target_key` varchar(32) COLLATE utf8mb4_general_ci GENERATED ALWAYS AS (concat(if((`library_kpi_id` is null),_utf8mb4'm',_utf8mb4'k'),coalesce(`library_kpi_id`,`library_metric_id`))) STORED,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ds_link` (`data_source_id`,`target_key`),
  KEY `idx_dsl_kpi` (`library_kpi_id`),
  KEY `idx_dsl_metric` (`library_metric_id`),
  CONSTRAINT `data_source_link_chk_1` CHECK (json_valid(`mappings`))
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
