DROP TABLE IF EXISTS `perf_metric`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `perf_metric` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `perf_kpi_id` bigint unsigned NOT NULL,
  `source_metric_id` bigint unsigned DEFAULT NULL,
  `name` varchar(500) NOT NULL,
  `catalog_code` varchar(20) DEFAULT NULL,
  `description` text,
  `category_id` varchar(40) DEFAULT NULL,
  `data_collect_method` varchar(500) DEFAULT NULL,
  `collection_period` enum('Q1','Q2','Q3','Q4','every_quarter') NOT NULL,
  `data_source_url` varchar(1000) DEFAULT NULL,
  `committee_id` varchar(30) DEFAULT NULL,
  `person_in_charge_id` varchar(20) DEFAULT NULL,
  `weight` decimal(6,2) NOT NULL DEFAULT '0.00',
  `unit` varchar(50) DEFAULT NULL,
  `five_year_target` decimal(14,4) DEFAULT NULL,
  `threshold_green` decimal(14,4) DEFAULT NULL,
  `threshold_amber` decimal(14,4) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_pmet_source` (`source_metric_id`),
  KEY `idx_pmet_kpi` (`perf_kpi_id`),
  CONSTRAINT `fk_pmet_kpi` FOREIGN KEY (`perf_kpi_id`) REFERENCES `perf_kpi` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_pmet_source` FOREIGN KEY (`source_metric_id`) REFERENCES `library_metric` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=268 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

