--
-- Table structure for table `perf_metric_quarter_progress`
--

DROP TABLE IF EXISTS `perf_metric_quarter_progress`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `perf_metric_quarter_progress` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `perf_metric_id` bigint unsigned NOT NULL,
  `year_no` tinyint unsigned NOT NULL,
  `quarter_no` tinyint unsigned NOT NULL,
  `progress_value` decimal(14,4) DEFAULT NULL,
  `variable1_value` decimal(14,4) DEFAULT NULL,
  `variable2_value` decimal(14,4) DEFAULT NULL,
  `is_computed` tinyint(1) NOT NULL DEFAULT '0',
  `issue` text,
  `solution` text,
  `recorded_by` varchar(255) DEFAULT NULL,
  `recorded_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pmet_period` (`perf_metric_id`,`year_no`,`quarter_no`),
  CONSTRAINT `fk_pmetqp` FOREIGN KEY (`perf_metric_id`) REFERENCES `perf_metric` (`id`) ON DELETE CASCADE,
  CONSTRAINT `perf_metric_quarter_progress_chk_1` CHECK ((`year_no` between 1 and 5)),
  CONSTRAINT `perf_metric_quarter_progress_chk_2` CHECK ((`quarter_no` between 1 and 4))
) ENGINE=InnoDB AUTO_INCREMENT=6825 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

